<?php require_once __DIR__.'/_base.php'; $title='Complaints'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('INSERT INTO complaints(user_id,provider_id,booking_id,subject,description,status) VALUES(?,?,?,?,?,?)')->execute([$u['id'],(int)$_POST['provider_id']?:null,(int)$_POST['booking_id']?:null,post('subject'),post('description'),'Open']);flash('success','Complaint submitted.');redirect('complaints.php');}$bs=$pdo->prepare('SELECT b.id,p.name FROM bookings b JOIN providers p ON p.id=b.provider_id WHERE b.user_id=? ORDER BY b.created_at DESC');$bs->execute([$u['id']]);$cs=$pdo->prepare('SELECT c.*,p.name provider_name FROM complaints c LEFT JOIN providers p ON p.id=c.provider_id WHERE c.user_id=? ORDER BY c.created_at DESC');$cs->execute([$u['id']]);?><div class="row g-4"><div class="col-lg-5"><div class="service-card p-4"><h4>Submit Complaint</h4><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Booking</label><select name="booking_id" class="form-select"><option value="0">General</option><?php foreach($bs->fetchAll() as $b):?><option value="<?=$b['id']?>">#<?=$b['id']?> — <?=e($b['name'])?></option><?php endforeach;?></select></div><input type="hidden" name="provider_id" value="0"><div class="mb-3"><label class="form-label">Subject</label><input name="subject" class="form-control" required></div><div class="mb-3"><label class="form-label">Description</label><textarea name="description" class="form-control" rows="5" required></textarea></div><button class="btn btn-success">Submit</button></form></div></div><div class="col-lg-7"><div class="service-card p-4"><h4>My Complaints</h4><?php foreach($cs->fetchAll() as $c):?><div class="border-bottom py-3"><div class="d-flex justify-content-between"><b><?=e($c['subject'])?></b><?=badge($c['status'])?></div><p class="small text-secondary"><?=e($c['description'])?></p><?php if($c['admin_response']):?><div class="alert alert-light mb-0"><b>Admin:</b> <?=e($c['admin_response'])?></div><?php endif;?></div><?php endforeach;?></div></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>